'use client';

import { useMemo, useRef } from 'react';
import { useTexture } from '@react-three/drei';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { depthPath, stillPath, type SceneData, type Theme } from '@/data/scenes';

/**
 * One scene as real geometry: a subdivided plane whose vertices are pushed back along
 * Z by the scene's depth map. Near pixels (white) stay forward, far pixels (black) sink
 * away, so moving the camera past it produces genuine parallax rather than sliding a
 * flat picture around.
 */

const SEGMENTS = 256; // 65k verts per scene; drop to 128 if the 1660 Ti struggles

const vertexShader = /* glsl */ `
  uniform sampler2D uDepth;
  uniform float uDepthScale;
  varying vec2 vUv;

  void main() {
    vUv = uv;
    // Depth maps are near = white, so invert: dark pixels get pushed furthest back.
    float depth = texture2D(uDepth, uv).r;
    vec3 displaced = position;
    displaced.z -= (1.0 - depth) * uDepthScale;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(displaced, 1.0);
  }
`;

const fragmentShader = /* glsl */ `
  uniform sampler2D uMap;
  uniform float uOpacity;
  varying vec2 vUv;

  void main() {
    gl_FragColor = texture2D(uMap, vUv);
    gl_FragColor.a *= uOpacity;
    #include <colorspace_fragment>
  }
`;

interface DepthSceneProps {
  scene: SceneData;
  theme: Theme;
  /** World position along the corridor. */
  z: number;
  /** Plane width in world units; height is derived from the image aspect. */
  width?: number;
}

export default function DepthScene({ scene, theme, z, width = 16 }: DepthSceneProps) {
  const materialRef = useRef<THREE.ShaderMaterial>(null);

  const [map, depth] = useTexture([
    stillPath(scene.id, theme),
    depthPath(scene.id, theme),
  ]);

  map.colorSpace = THREE.SRGBColorSpace;
  // The depth map is data, not colour — decoding it as sRGB would skew the displacement.
  depth.colorSpace = THREE.NoColorSpace;

  const source = map.image as { width: number; height: number } | undefined;
  const aspect = source ? source.width / source.height : 16 / 9;
  const height = width / aspect;

  const uniforms = useMemo(
    () => ({
      uMap: { value: map },
      uDepth: { value: depth },
      uDepthScale: { value: scene.depthScale },
      uOpacity: { value: 1 },
    }),
    [map, depth, scene.depthScale]
  );

  // Fade the plate out as the camera passes through it, so scenes hand over rather
  // than clipping through each other.
  useFrame((state) => {
    const mat = materialRef.current;
    if (!mat) return;
    const distance = state.camera.position.z - z;
    const fade = THREE.MathUtils.smoothstep(distance, 0, 8);
    mat.uniforms.uOpacity.value = fade;
  });

  return (
    <mesh position={[0, 0, z]}>
      <planeGeometry args={[width, height, SEGMENTS, SEGMENTS]} />
      <shaderMaterial
        ref={materialRef}
        uniforms={uniforms}
        vertexShader={vertexShader}
        fragmentShader={fragmentShader}
        transparent
      />
    </mesh>
  );
}

