'use client';

import { Suspense } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { AdaptiveDpr, Preload, ScrollControls, useScroll } from '@react-three/drei';
import * as THREE from 'three';
import { scenes, type Theme } from '@/data/scenes';
import DepthScene from './DepthScene';

/** Distance between scenes along the corridor. */
const SPACING = 26;
/** How far in front of a plate the camera sits when that scene is centred. */
const CAMERA_OFFSET = 9;

const sceneZ = (index: number) => -index * SPACING;
const travel = (scenes.length - 1) * SPACING;

/**
 * Nothing on the page actually scrolls. ScrollControls turns the wheel into a single
 * 0→1 float, and that float walks the camera down the corridor. damp() is what makes
 * it feel cinematic rather than glued to the wheel — the camera chases a target it
 * never quite catches, framerate-independently.
 */
function CameraRig() {
  const scroll = useScroll();
  const { camera } = useThree();

  useFrame((state, delta) => {
    const progress = scroll.offset;

    const targetZ = CAMERA_OFFSET - progress * travel;
    camera.position.z = THREE.MathUtils.damp(camera.position.z, targetZ, 4, delta);

    // Pointer drift, so the world breathes even when the viewer is still.
    const targetRotY = -state.pointer.x * 0.06;
    const targetRotX = state.pointer.y * 0.035;
    camera.rotation.y = THREE.MathUtils.damp(camera.rotation.y, targetRotY, 3, delta);
    camera.rotation.x = THREE.MathUtils.damp(camera.rotation.x, targetRotX, 3, delta);
  });

  return null;
}

/** Renders only the scenes near the camera; the rest stay unmounted. */
function Corridor({ theme }: { theme: Theme }) {
  return (
    <>
      {scenes.map((scene, i) => (
        <Suspense key={`${scene.id}-${theme}`} fallback={null}>
          <DepthScene scene={scene} theme={theme} z={sceneZ(i)} />
        </Suspense>
      ))}
    </>
  );
}

export default function World({ theme }: { theme: Theme }) {
  return (
    <Canvas
      dpr={[1, 2]}
      gl={{ antialias: true }}
      camera={{ position: [0, 0, CAMERA_OFFSET], fov: 60, near: 0.1, far: 400 }}
      style={{ position: 'fixed', inset: 0 }}
    >
      <color attach="background" args={['#05040a']} />
      <ambientLight intensity={1} />

      <ScrollControls pages={scenes.length} damping={0.35}>
        <CameraRig />
        <Corridor theme={theme} />
      </ScrollControls>

      <Preload all />
      <AdaptiveDpr pixelated />
    </Canvas>
  );
}
